<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed} from 'vue'
import {api,artifactBlob,downloadArtifact} from '../api'
import DOMPurify from 'dompurify'
import {usePresentationPreview} from '../composables/usePresentationPreview'
const props=defineProps<{id:string;name:string}>(),emit=defineEmits<{close:[]}>()
const data=ref<Record<string,any>>({}),error=ref(''),loading=ref(true),blob=ref('')
const slides=usePresentationPreview(()=>props.id)
let disposed=false
const html=computed(()=>`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data: blob:; font-src data:"><style>body{font:15px/1.8 system-ui;margin:28px;overflow-wrap:anywhere}</style>`+DOMPurify.sanitize(data.value.content||''))
function closeKey(e:KeyboardEvent){if(e.key==='Escape')emit('close')}
onMounted(async()=>{document.addEventListener('keydown',closeKey);try{const result=await api.get<Record<string,any>>(`/api/operations/artifacts/${props.id}/preview`);if(disposed)return;data.value=result;if(result.type==='presentation')await slides.load(1);if(['pdf','image'].includes(result.type)){const file=await artifactBlob(props.id);if(disposed)return;blob.value=URL.createObjectURL(file)}}catch(e){error.value=(e as Error).message}finally{if(!disposed)loading.value=false}})
onBeforeUnmount(()=>{disposed=true;document.removeEventListener('keydown',closeKey);if(blob.value)URL.revokeObjectURL(blob.value)})
</script>
<template><div class="artifact-overlay" @click.self="emit('close')"><section class="artifact-dialog" role="dialog" aria-modal="true" :aria-label="'预览 '+name"><header><h2>{{ name }}</h2><div><button class="btn" @click="downloadArtifact(id)">下载</button><button class="btn" aria-label="关闭产物预览" @click="emit('close')">关闭</button></div></header><p v-if="loading" class="muted">正在读取产物…</p><p v-else-if="error" class="error">{{ error }}</p><section v-else-if="data.type==='presentation'" class="slide-preview"><nav><button class="btn" :disabled="slides.loading.value||slides.page.value <= 1" @click="slides.load(slides.page.value-1)">上一页</button><span>{{ slides.page.value }} / {{ data.slideCount }}</span><button class="btn" :disabled="slides.loading.value||slides.page.value >= data.slideCount" @click="slides.load(slides.page.value+1)">下一页</button><button v-if="slides.error.value" class="btn" @click="slides.load(slides.page.value)">重试</button></nav><p v-if="slides.loading.value" class="muted" role="status">正在渲染幻灯片…</p><p v-if="slides.error.value" class="error" role="alert">{{ slides.error.value }}</p><img v-if="slides.url.value" :src="slides.url.value" :alt="name+' 第 '+slides.page.value+' 页'" /><small>{{ data.notice }}</small></section><iframe v-else-if="data.type==='html'" :srcdoc="html" sandbox="" title="网页产物预览" /><iframe v-else-if="data.type==='pdf'" :src="blob" title="PDF 产物预览" /><img v-else-if="data.type==='image'" :src="blob" :alt="name" /><div v-else-if="data.type==='table'" class="table-scroll"><small>显示前100行、30列；完整数据可下载。</small><table><tbody><tr v-for="(row,i) in data.rows" :key="i"><td v-for="(cell,j) in row" :key="j">{{ cell }}</td></tr></tbody></table></div><pre v-else-if="data.type==='text'">{{ data.content }}</pre><p v-else>此格式暂不支持内嵌预览，请下载查看。</p></section></div></template>
<style scoped>.artifact-overlay{position:fixed;inset:0;z-index:80;display:grid;place-items:center;background:#16241b70;backdrop-filter:blur(5px);padding:32px}.artifact-dialog{background:var(--ink-2);border-radius:16px;border:1px solid var(--line);width:min(1100px,96vw);height:min(820px,90vh);padding:24px;display:flex;flex-direction:column;color:var(--txt-1);min-height:0}.artifact-dialog header{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:18px}.artifact-dialog header div{display:flex;gap:8px}h2{font-size:17px;margin:0;overflow-wrap:anywhere}iframe{border:1px solid var(--line);border-radius:8px;background:white;flex:1;min-height:0;width:100%}img{max-width:100%;min-height:0;object-fit:contain}pre{overflow:auto;white-space:pre-wrap;font:13px/1.9 var(--font-ui)}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}td{border:1px solid var(--line);padding:9px;max-width:350px;overflow-wrap:anywhere}.error{color:var(--red)}small{color:var(--txt-3)}.slide-preview{display:flex;flex:1;min-height:0;flex-direction:column;gap:12px}.slide-preview nav{display:flex;align-items:center;justify-content:center;gap:18px}.slide-preview img{flex:1;min-height:0;object-fit:contain;background:#f7f8f5;border:1px solid var(--line)}.slide-preview small{text-align:center}</style>
